				itemId,
				itemName: getItemName(type, itemId),
				amount,
				operationCount: craftPlan.operations?.length ?? 0,
				directInventoryAmount: getInventoryAmount(runtimeCraftState.inventory, type, itemId),
				planningInventoryAmount: getInventoryAmount(planningState.inventory, type, itemId),
				goldAvailable: runtimeCraftState.goldAvailable,
				planningGoldAvailable: planningState.gold,
